command:
tmpdir=$(mktemp -d)
printf '%s\n' '{"tasks":[]}' > "$tmpdir/empty.json"
printf '%s\n' '{"tasks":[{"id":"deploy","duration":2,"dependsOn":["test","build"]},{"id":"test","duration":4,"dependsOn":["lint"]},{"id":"build","duration":3,"dependsOn":["lint"]},{"id":"lint","duration":1},{"id":"docs","duration":4}]}' > "$tmpdir/main.json"
printf '%s\n' '{"tasks":[{"id":"z","duration":0,"dependsOn":["a"]},{"id":"a","duration":0},{"id":"b","duration":0}]}' > "$tmpdir/zero.json"
printf '%s\n' '{"tasks":[{"id":"end","duration":1,"dependsOn":["beta","alpha"]},{"id":"beta","duration":2,"dependsOn":["root"]},{"id":"alpha","duration":2,"dependsOn":["root"]},{"id":"root","duration":1}]}' > "$tmpdir/tie.json"
printf '%s\n' '{"tasks":[{"id":"c","duration":1,"dependsOn":["b"]},{"id":"a","duration":1,"dependsOn":["c"]},{"id":"b","duration":1,"dependsOn":["a"]}]}' > "$tmpdir/cycle.json"
actual=$(bun run src/cli.ts plan "$tmpdir/empty.json")
test "$actual" = '{"order":[],"layers":[],"earliest":{},"totalDuration":0,"criticalPath":[]}' || { echo "empty mismatch: $actual"; exit 1; }
actual=$(bun run src/cli.ts plan "$tmpdir/main.json")
test "$actual" = '{"order":["docs","lint","build","test","deploy"],"layers":[["docs","lint"],["build","test"],["deploy"]],"earliest":{"docs":{"start":0,"finish":4},"lint":{"start":0,"finish":1},"build":{"start":1,"finish":4},"test":{"start":1,"finish":5},"deploy":{"start":5,"finish":7}},"totalDuration":7,"criticalPath":["lint","test","deploy"]}' || { echo "main mismatch: $actual"; exit 1; }
actual=$(bun run src/cli.ts plan "$tmpdir/zero.json")
test "$actual" = '{"order":["a","b","z"],"layers":[["a","b"],["z"]],"earliest":{"a":{"start":0,"finish":0},"b":{"start":0,"finish":0},"z":{"start":0,"finish":0}},"totalDuration":0,"criticalPath":["a"]}' || { echo "zero mismatch: $actual"; exit 1; }
actual=$(bun run src/cli.ts plan "$tmpdir/tie.json")
test "$actual" = '{"order":["root","alpha","beta","end"],"layers":[["root"],["alpha","beta"],["end"]],"earliest":{"root":{"start":0,"finish":1},"alpha":{"start":1,"finish":3},"beta":{"start":1,"finish":3},"end":{"start":3,"finish":4}},"totalDuration":4,"criticalPath":["root","alpha","end"]}' || { echo "tie mismatch: $actual"; exit 1; }
cycle_err=$(bun run src/cli.ts plan "$tmpdir/cycle.json" 2>&1 >/dev/null); cycle_status=$?
test "$cycle_status" -ne 0 || { echo 'cycle unexpectedly succeeded'; exit 1; }
test "$cycle_err" = 'Error: dependency cycle: a -> c -> b -> a' || { echo "cycle mismatch: $cycle_err"; exit 1; }
echo 'positive and cycle tests passed'

